function isNumeric(str) {
  // Verifica se la stringa è vuota o contiene solo spazi
  if (str.trim() === "") {
    return false;
  }
  
  // Controlla se la stringa contiene solo numeri usando una regex
  return /^\d+$/.test(str);
}


